// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class ServiceTest {

	/** Every VALUES column inside the service pattern is a service variable, even one with an UNDEF row. */
	@Test
	void valuesColumnWithUndefRowIsServiceVar() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		MapBindingSet first = new MapBindingSet();
		first.addBinding("s", vf.createIRI("urn:a"));
		MapBindingSet second = new MapBindingSet();
		second.addBinding("s", vf.createIRI("urn:b"));
		second.addBinding("y", vf.createLiteral(1));
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(List.of(first, second));
		Join pattern = new Join(values, new StatementPattern(Var.of("s"), Var.of("p", vf.createIRI("urn:p")),
				Var.of("o")));

		Service service = new Service(Var.of("srv", vf.createIRI("urn:x")), pattern, "{ ?s <urn:p> ?o }", Map.of(),
				null, false);

		assertThat(service.getServiceVars()).containsExactlyInAnyOrder("s", "y", "o");
	}

	@Test
	void projectionExpressionVariablesAreServiceVars() {
		ProjectionElem projectionElem = new ProjectionElem("u");
		projectionElem.setSourceExpression(new ExtensionElem(Var.of("x"), "u"));
		Projection projection = new Projection(new EmptySet(), new ProjectionElemList(projectionElem));

		Service service = new Service(Var.of("srv", SimpleValueFactory.getInstance().createIRI("urn:x")),
				projection, "SELECT (?x AS ?u) WHERE {}", Map.of(), null, false);

		assertThat(service.getServiceVars()).containsExactlyInAnyOrder("u", "x");
	}

	@Test
	void preboundNamedVariableIsServiceOutputButNotInput() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		StatementPattern pattern = new StatementPattern(Var.of("s", vf.createIRI("urn:bound")), Var.of("p"),
				Var.of("o"));
		Service service = new Service(Var.of("srv", vf.createIRI("urn:x")), pattern, "{ ?s ?p ?o }", Map.of(),
				null, false);

		assertThat(service.getServiceOutputBindingNames()).contains("s");
		assertThat(service.getServiceInputBindingNames()).doesNotContain("s");
	}

	@Test
	void trueConstantNamedVariableIsNeitherServiceOutputNorInput() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		StatementPattern pattern = new StatementPattern(Var.of("s", vf.createIRI("urn:constant"), false, true),
				Var.of("p"), Var.of("o"));
		Service service = new Service(Var.of("srv", vf.createIRI("urn:x")), pattern, "{ <urn:constant> ?p ?o }",
				Map.of(), null, false);

		assertThat(service.getServiceOutputBindingNames()).doesNotContain("s");
		assertThat(service.getServiceInputBindingNames()).doesNotContain("s");
	}

	@Test
	void explicitRowIndexVariableEndpointRemainsServiceInput() {
		Projection projection = new Projection(new SingletonSet(),
				new ProjectionElemList(new ProjectionElem("__rowIdx")), true);
		Service service = new Service(Var.of("__rowIdx"), projection,
				"SELECT ?__rowIdx WHERE {}", Map.of(), null, false);

		assertThat(service.getServiceInputBindingNames()).contains("__rowIdx");
	}

	@Test
	void explicitRowIndexBodyReadRemainsServiceInput() {
		Filter filter = new Filter(new SingletonSet(), new Bound(Var.of("__rowIdx")));
		Projection projection = new Projection(filter,
				new ProjectionElemList(new ProjectionElem("__rowIdx")), true);
		Service service = new Service(Var.of("service", SimpleValueFactory.getInstance().createIRI("urn:x")),
				projection, "SELECT ?__rowIdx WHERE { FILTER(BOUND(?__rowIdx)) }", Map.of(), null, false);

		assertThat(service.getServiceInputBindingNames()).contains("__rowIdx");
	}
}
